          description: '你身上有一件事，从来没有跟任何人说完整过：一种想要、一段关系、一个你在深夜里反复回到的场面。它不一定是脏的，但它是**不体面的**，而在邓威克，不体面就够了。你把它压下去，压了很多年，压得很好。蜕相把这个"压"变成了本事：你能忍、能熬、能在别人都散架的时候继续做事。但它同时是八相里最饿的一相。你压下去的东西没有消失，它在另一侧长大；你什么时候会听见它敲门，取决于你哪一天晚上独自待得太久。',
          attributeBonus: { molt: 3 },
