          description: '你比谁都守时——不是因为你道德，是因为你听见了。城市有它自己的节拍：汽笛、教堂钟、电报局的收报机、太平间门口那辆车的马蹄声，而你能听出什么时候其中一样会慢半拍。钟相让时刻、名称与约定在你手里变得可操作：你按点敲门，对方就开；你说出一个名字，那个名字就被记住。它要的代价是应答——你敲响的东西会回答你，而回答你的不一定是你叫的那一个。你至今记得那个深夜，你听见有人在门外叫你的名字，用的是你自己的嗓音。',
          attributeBonus: { bell: 3 },
