          description: '你曾经有一个姐姐（或者妹妹）。她十七岁那年"去乡下调养"，然后你就再也没有见过她。家里人说过三种说法：她身体不好、她嫁到很远的地方、她死了。三种说法你都听过，而且都出自同一个人，时间不同。你现在知道"调养"这个词在邓威克是什么意思：城北那几家疗养院的登记簿上，有一整栏写的都是这个词，而进去的人大多数没有出来。你留着她给你的一件小东西，每年拿出来看一次。',
